mapper.select:
SELECT * FROM ( SELECT ROWNUM AS rn, t.* FROM ( SELECT u.userIdx, u.userId, u.name, u.nickname, u.email, u.tel, u.status, u.createdDate, u.lastLoginDate, u.profile_photo, u.score, u.userLevel, u.batonpoint, a.authority FROM users u LEFT JOIN userAuthority a ON u.userId = a.userId
AND u.userId LIKE '%' || #{kwd} || '%' AND u.nickname LIKE '%' || #{kwd} || '%' AND u.email LIKE '%' || #{kwd} || '%' AND (u.userId LIKE '%' || #{kwd} || '%' OR u.nickname LIKE '%' || #{kwd} || '%')
AND u.status = #{status}
ORDER BY u.createdDate DESC ) t WHERE ROWNUM <= #{offset} + #{pageSize} ) WHERE rn > #{offset}

SELECT COUNT(*) FROM users u
AND u.userId LIKE '%' || #{kwd} || '%' AND u.nickname LIKE '%' || #{kwd} || '%' AND u.email LIKE '%' || #{kwd} || '%' AND (u.userId LIKE '%' || #{kwd} || '%' OR u.nickname LIKE '%' || #{kwd} || '%')
AND u.status = #{status}

mapper.update:
UPDATE adminSanction
SET isLifted = 1, liftReason = #{liftReason}, liftDate = CURRENT_TIMESTAMP
WHERE sanctionIdx = #{sanctionIdx}

mapper.select:
SELECT * FROM ( SELECT ROWNUM AS rn, t.* FROM ( SELECT w.withdrawIdx, w.userIdx, w.reason, TO_CHAR(w.requestDate, 'YYYY-MM-DD HH24:MI') AS requestDate, w.withdrawStatus, u.userId, u.nickname, u.email, u.createdDate, u.batonpoint, (SELECT COUNT(*) FROM adminReport r WHERE r.reportedUserIdx = w.userIdx AND r.processStatus = 0) AS pendingReports, (SELECT COUNT(*) FROM TRADETRANSACTION t2 WHERE (t2.BUYERIDX = w.userIdx OR t2.SELLERIDX = w.userIdx) AND t2.TRADESTATUS NOT IN ('COMPLETED','CANCELLED')) AS activeTrades FROM withdrawRequest w JOIN users u ON w.userIdx = u.userIdx
AND (u.userId LIKE '%' || #{kwd} || '%' OR u.nickname LIKE '%' || #{kwd} || '%')
AND w.withdrawStatus = #{wFilter}
ORDER BY w.requestDate DESC ) t WHERE ROWNUM <= #{offset} + #{pageSize} ) WHERE rn > #{offset}

SELECT COUNT(*) FROM withdrawRequest w JOIN users u ON w.userIdx = u.userIdx
AND (u.userId LIKE '%' || #{kwd} || '%' OR u.nickname LIKE '%' || #{kwd} || '%')
AND w.withdrawStatus = #{wFilter}
